using System.Collections.Immutable;
using StructuralLoadAssistant.Domain;
using StructuralLoadAssistant.Engineering;

namespace StructuralLoadAssistant.Tests;

public sealed class EngineeringTests
{
    private static readonly WindState State = new(WindDirection.PositiveX, "IP+", "Wall", LimitState.Uls);
    private static FrameGeometry Beam(string id, double z, double x1 = 0, double x2 = 10, string facade = "F") => new(id, facade, new(x1,0,z), new(x2,0,z));

    [Fact] public void SiUnits_ConvertAndMultiply() { Assert.Equal(1200,Pressure.FromKPa(1.2).Pa); Assert.Equal(1.2,Pressure.FromKPa(1.2).KPa); Assert.Equal(2100,LineLoad.FromKNPerM(2.1).NPerM); Assert.Equal(3.6,Pressure.FromKPa(1.2).Over(new Length(3)).KNPerM); }
    [Theory] [InlineData(0,1200)] [InlineData(1.5,1400)] [InlineData(3,1600)] public void Interpolation_EndpointsAndMidpoint(double x,double expected) => Assert.Equal(expected,EngineeringMath.Linear(x,0,1200,3,1600),8);
    [Fact] public void Integral_ConstantAndCubic() { Assert.Equal(3600,EngineeringMath.Integrate(_=>1200,0,3),7); Assert.Equal(20.25,EngineeringMath.Integrate(z=>z*z*z,0,3),8); }
    [Theory] [InlineData(0)] [InlineData(-1)] [InlineData(double.NaN)] [InlineData(double.PositiveInfinity)] public void Facade_RejectsInvalidHeight(double height) => Assert.Throws<ArgumentException>(()=>FacadeDistribution.Calculate(1,2,height,FacadeMethod.EqualSplit));
    [Fact] public void Math_RejectsNonfiniteInputsAndProfiles() { Assert.Throws<ArgumentException>(()=>EngineeringMath.Linear(1,0,2,0,3)); Assert.Throws<ArgumentException>(()=>EngineeringMath.Integrate(_=>double.NaN,0,1)); Assert.Throws<ArgumentException>(()=>Pressure.FromKPa(double.PositiveInfinity)); Assert.Throws<ArgumentException>(()=>FacadeDistribution.Calculate(double.NaN,1,3,FacadeMethod.EqualSplit)); }
    [Fact] public void Facade_EqualSplit_P1_1p2_P2_1p6_H3_Returns2p1Each() { var r=FacadeDistribution.Calculate(1200,1600,3,FacadeMethod.EqualSplit); Assert.Equal(2100,r.LowerNPerM,8); Assert.Equal(2100,r.UpperNPerM,8); Assert.Equal(r.ResultantNPerM,r.LowerNPerM+r.UpperNPerM,8); }
    [Fact] public void Facade_StaticEquivalent_P1_1p2_P2_1p6_H3_Returns2p0And2p2() { var r=FacadeDistribution.Calculate(1200,1600,3,FacadeMethod.StaticallyEquivalent); Assert.Equal(2000,r.LowerNPerM,8); Assert.Equal(2200,r.UpperNPerM,8); Assert.Equal(r.FirstMomentN,r.UpperNPerM*3,8); Assert.Equal(4200,r.ResultantNPerM,8); }
    [Fact] public void Facade_NonlinearProfileMatchesAnalyticMoment() { var r=FacadeDistribution.Integrate(z=>1000*z*z,0,3,FacadeMethod.StaticallyEquivalent); Assert.Equal(9000,r.ResultantNPerM,7); Assert.Equal(6750,r.UpperNPerM,7); Assert.Equal(2250,r.LowerNPerM,7); }
    [Fact] public void Facade_OpposingPressureCancellationWarns() { var r=FacadeDistribution.Calculate(-1000,1000,3,FacadeMethod.EqualSplit); Assert.Equal(0,r.ResultantNPerM,7); Assert.NotEmpty(r.Warnings); Assert.Equal(1500,r.FirstMomentN,7); }
    [Fact] public void GlobalForce_InwardAtXPositivePointsNegativeX() { Assert.Equal(new Vec3(-1200,0,0),EngineeringMath.GlobalForce(1200,new(1,0,0))); Assert.Equal(3,EngineeringMath.WindHeight(103,100)); Assert.Throws<ArgumentException>(()=>EngineeringMath.WindHeight(99,100)); }
    [Fact] public void Facade_StackedPanelsAccumulateMiddleBeam() { var a=FacadeMapper.MapPair(Beam("B1",3),Beam("B2",6),_=>1400,0,State,"WX",FacadeMethod.EqualSplit); var b=FacadeMapper.MapPair(Beam("B2",6),Beam("B3",9),_=>2000,0,State,"WX",FacadeMethod.EqualSplit); var all=FacadeMapper.Accumulate(a.Concat(b)); Assert.Equal(5100,all.Single(x=>x.FrameId=="B2").LoadNPerM); }
    [Fact] public void Facade_DifferentLengthsUseActualOverlapAndSplitAccumulation() { var a=FacadeMapper.MapPair(Beam("L",0),Beam("U1",3,0,5),_=>1000,0,State,"WX",FacadeMethod.EqualSplit); var b=FacadeMapper.MapPair(Beam("L",0),Beam("U2",3,5,10),_=>2000,0,State,"WX",FacadeMethod.EqualSplit); var lower=FacadeMapper.Accumulate(a.Concat(b)).Where(x=>x.FrameId=="L").ToArray(); Assert.Equal(2,lower.Length); Assert.Equal(0,lower[0].StartFraction); Assert.Equal(0.5,lower[0].EndFraction); Assert.Equal(1500,lower[0].LoadNPerM); Assert.Equal(3000,lower[1].LoadNPerM); }
    [Fact] public void Facade_RejectsNoOverlapAndAmbiguousAndSloping() { Assert.Throws<ArgumentException>(()=>FacadeMapper.MapPair(Beam("L",0),Beam("U",3,11,20),_=>1,0,State,"WX",FacadeMethod.EqualSplit)); Assert.Throws<ArgumentException>(()=>FacadeMapper.MapPair(Beam("L",0),Beam("U",3,0,10,"G"),_=>1,0,State,"WX",FacadeMethod.EqualSplit)); Assert.Throws<ArgumentException>(()=>FacadeMapper.MapPair(Beam("L",0),new("U","F",new(0,0,3),new(10,0,4)),_=>1,0,State,"WX",FacadeMethod.EqualSplit)); Assert.Throws<ArgumentException>(()=>FacadeMapper.MapPair(Beam("L",0),new("U","F",new(0,1,3),new(10,1,3)),_=>1,0,State,"WX",FacadeMethod.EqualSplit)); }
    [Fact] public void Facade_ReversedFramesAndDatumAreHandled() { var r=FacadeMapper.MapPair(Beam("L",103,10,0),Beam("U",106,2,5),z=>1000*z,100,State,"WX",FacadeMethod.EqualSplit); Assert.Equal(0.5,r[0].StartFraction,8); Assert.Equal(0.8,r[0].EndFraction,8); Assert.Equal(6750,r[0].LoadNPerM,7); }
    [Fact] public void Facade_AccumulationKeepsStatesAndPatternsSeparate() { var r=new FrameSegmentLoad("B",State,"WX",0,1,100); Assert.Equal(3,FacadeMapper.Accumulate([r,r with {Pattern="WY"},r with {State=State with {InternalPressure="IP-"}}]).Length); }
    [Fact] public void Wall_LoadUsesIndependentHeightOpeningsAndFinishes() { var input=new WallInput(new("Test",0.2,20000,100,200),2,5,0.25,"WALL","B"); var r=WallLoads.Calculate(input); Assert.Equal(9675,r.TotalNPerM); Assert.Equal(new Vec3(0,0,-9675),r.GlobalLoadNPerM); Assert.False(r.IsOverride); Assert.True(WallLoads.DemoLibrary.Length>=2); }
    [Fact] public void Wall_DirectOverrideAndInvalidDimensions() { var input=new WallInput(new("Test",0.2,20000,100,200),0,3,0,"WALL","B",2500); Assert.Equal(2500,WallLoads.Calculate(input).TotalNPerM); Assert.True(WallLoads.Calculate(input).IsOverride); Assert.Throws<ArgumentException>(()=>WallLoads.Calculate(input with {TopM=0})); Assert.Throws<ArgumentException>(()=>WallLoads.Calculate(input with {OpeningsFraction=1.1})); }
    [Fact] public void Standards_MissingCoefficientsAlwaysBlockAndDemoNeverVerified() { var manifest=new StandardManifest("ASCE","7-22",[],StandardDataVerificationStatus.VerifiedForUse,[]); var a=StandardsGate.Check(manifest,DataProvenance.Verified); Assert.False(a.CanAssignRealModel); Assert.Equal(StandardsGateStatus.NeedsVerifiedStandardsData,a.Status); Assert.NotEmpty(a.MissingData); var demo=StandardsGate.Check(manifest,DataProvenance.SyntheticDemoFixture); Assert.Equal(StandardsGateStatus.SyntheticDemoOnly,demo.Status); Assert.False(demo.CanAssignRealModel); }
    [Fact] public void Standards_TypedAsceInputBlocksWithoutInventingPressure() { var input=new AsceWindInput(40,AsceRiskCategory.II,AsceExposure.C,100,10,LimitState.Uls,"Licensed source pending"); var manifest=new StandardManifest("ASCE/SEI 7","7-22",[],StandardDataVerificationStatus.Missing,[]); var result=StandardCalculators.Asce7_22(input,manifest); Assert.Null(result.Run); Assert.False(result.Gate.CanAssignRealModel); Assert.Contains("Velocity pressure",result.RequiredStages); Assert.Throws<ArgumentException>(()=>StandardCalculators.Asce7_22(input with {BasicWindSpeedMPerS=double.NaN},manifest)); }
    [Fact] public void Standards_CanonicalFullEditionNamesRemainGated() { var asce=new StandardManifest("ASCE/SEI 7","ASCE/SEI 7-22",[],StandardDataVerificationStatus.Missing,[]); var asnz=new StandardManifest("AS/NZS 1170.2","AS/NZS 1170.2:2021",[],StandardDataVerificationStatus.Missing,[]); Assert.False(StandardCalculators.Asce7_22(new(40,AsceRiskCategory.II,AsceExposure.C,0,10,LimitState.Uls,"source"),asce).Gate.CanAssignRealModel); Assert.False(StandardCalculators.AsNz1170_2_2021(new("A",500,AsNzTerrainCategory.TC2Point5,10,LimitState.Uls),asnz).Gate.CanAssignRealModel); }
    [Fact] public void Standards_TerrainTwoPointFiveAndLockedEditionGate() { var input=new AsNzWindInput("A",500,AsNzTerrainCategory.TC2Point5,10,LimitState.Uls); var manifest=new StandardManifest("AS/NZS 1170.2","2021",["Amendment 1:2023","Amendment 2:2024"],StandardDataVerificationStatus.Missing,[]); var result=StandardCalculators.AsNz1170_2_2021(input,manifest); Assert.Null(result.Run); Assert.Contains("Terrain/height multiplier",result.RequiredStages); Assert.Throws<ArgumentException>(()=>StandardCalculators.AsNz1170_2_2021(input,manifest with {Edition="2011"})); }
    [Fact] public void Units_ConstructorsAndIntegrationRejectInvalidDimensions() { Assert.Throws<ArgumentException>(()=>new Length(-1)); Assert.Throws<ArgumentException>(()=>new Pressure(double.NaN)); Assert.Throws<ArgumentException>(()=>new LineLoad(double.PositiveInfinity)); Assert.Throws<ArgumentException>(()=>EngineeringMath.Integrate(z=>z,0,1,3)); Assert.Throws<ArgumentException>(()=>EngineeringMath.GlobalForce(1,new(0,0,0))); }
}
